import{_ as d,o as e,c as o,a6 as r}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"字段速查表","description":"全部字段按 A–Z 索引——方向、语法要点、是否逐跳，链到详解。","frontmatter":{"title":"字段速查表","description":"全部字段按 A–Z 索引——方向、语法要点、是否逐跳，链到详解。","source":"https://daiw.org/manual/http11/field-index"},"headers":[],"relativePath":"manual/computer-programming/http11/field-index.md","filePath":"manual/computer-programming/http11/field-index.md"}'),a={name:"manual/computer-programming/http11/field-index.md"};function n(c,t,l,m,i,g){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="字段速查表" tabindex="-1">字段速查表 <a class="header-anchor" href="#字段速查表" aria-label="Permalink to &quot;字段速查表&quot;">​</a></h1><p>方向：<strong>Req</strong> = 请求，<strong>Res</strong> = 响应，<strong>Rep</strong> = 表示字段（两侧皆可）。逐跳字段以 <strong>⚠️</strong> 标注（代理必须剥离）。</p><h2 id="a–c" tabindex="-1">A–C <a class="header-anchor" href="#a–c" aria-label="Permalink to &quot;A–C&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>方向</th><th>语法要点</th><th>详解</th></tr></thead><tbody><tr><td><code>Accept</code></td><td>Req</td><td><code>#( media-range [ weight ] )</code>；特异性优先于 q</td><td><a href="/Front2Full/manual/computer-programming/http11/content-negotiation">协商</a></td></tr><tr><td><code>Accept-Charset</code></td><td>Req</td><td><strong>已废弃</strong>，勿用</td><td><a href="/Front2Full/manual/computer-programming/http11/content-negotiation">协商</a></td></tr><tr><td><code>Accept-Encoding</code></td><td>Req</td><td>空值 = 只接受 <code>identity</code></td><td><a href="/Front2Full/manual/computer-programming/http11/content-negotiation">协商</a></td></tr><tr><td><code>Accept-Language</code></td><td>Req</td><td>语言范围 + q；子标签数不影响排序</td><td><a href="/Front2Full/manual/computer-programming/http11/content-negotiation">协商</a></td></tr><tr><td><code>Accept-Patch</code></td><td>Res</td><td><code>#media-type</code></td><td><a href="/Front2Full/manual/computer-programming/http11/context-fields">上下文</a></td></tr><tr><td><code>Accept-Ranges</code></td><td>Res</td><td><code>bytes</code> / <code>none</code></td><td><a href="/Front2Full/manual/computer-programming/http11/range-requests">范围</a></td></tr><tr><td><code>Age</code></td><td>Res</td><td><code>delta-seconds</code>，缓存添加</td><td><a href="/Front2Full/manual/computer-programming/http11/caching">缓存</a></td></tr><tr><td><code>Allow</code></td><td>Res</td><td><code>#method</code>；<code>405</code> 中必需</td><td><a href="/Front2Full/manual/computer-programming/http11/methods">方法</a></td></tr><tr><td><code>Authentication-Info</code></td><td>Res</td><td><code>#auth-param</code></td><td><a href="/Front2Full/manual/computer-programming/http11/authentication">认证</a></td></tr><tr><td><code>Authorization</code></td><td>Req</td><td><code>auth-scheme SP (token68 / #auth-param)</code></td><td><a href="/Front2Full/manual/computer-programming/http11/authentication">认证</a></td></tr><tr><td><code>Cache-Control</code></td><td>Req/Res</td><td><code>#cache-directive</code>；未知指令须忽略</td><td><a href="/Front2Full/manual/computer-programming/http11/caching">缓存</a></td></tr><tr><td><code>Connection</code></td><td>Req/Res ⚠️</td><td>列逐跳字段名 + <code>close</code></td><td><a href="/Front2Full/manual/computer-programming/http11/connection-management">连接</a></td></tr><tr><td><code>Content-Disposition</code></td><td>Res</td><td><code>attachment; filename*=UTF-8&#39;&#39;…</code></td><td><a href="/Front2Full/manual/computer-programming/http11/context-fields">上下文</a></td></tr><tr><td><code>Content-Encoding</code></td><td>Rep</td><td>端到端；改变 ETag</td><td><a href="/Front2Full/manual/computer-programming/http11/representation-fields">表示</a></td></tr><tr><td><code>Content-Language</code></td><td>Rep</td><td><code>#language-tag</code>，指受众</td><td><a href="/Front2Full/manual/computer-programming/http11/representation-fields">表示</a></td></tr><tr><td><code>Content-Length</code></td><td>Rep</td><td><strong>十进制</strong>；与 TE 冲突时无效</td><td><a href="/Front2Full/manual/computer-programming/http11/message-body-length">成帧</a></td></tr><tr><td><code>Content-Location</code></td><td>Rep</td><td>本表示的 URI，非重定向</td><td><a href="/Front2Full/manual/computer-programming/http11/representation-fields">表示</a></td></tr><tr><td><code>Content-Range</code></td><td>Res</td><td><code>bytes SP 0-499/10000</code>（<strong>SP</strong> 非 <code>=</code>）</td><td><a href="/Front2Full/manual/computer-programming/http11/range-requests">范围</a></td></tr><tr><td><code>Content-Type</code></td><td>Rep</td><td><code>type/subtype</code> + 参数</td><td><a href="/Front2Full/manual/computer-programming/http11/representation-fields">表示</a></td></tr><tr><td><code>Cookie</code></td><td>Req</td><td><code>;</code> 分隔；<strong>只有名值对</strong></td><td><a href="/Front2Full/manual/computer-programming/http11/cookies">Cookie</a></td></tr></tbody></table><h2 id="d–l" tabindex="-1">D–L <a class="header-anchor" href="#d–l" aria-label="Permalink to &quot;D–L&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>方向</th><th>语法要点</th><th>详解</th></tr></thead><tbody><tr><td><code>Date</code></td><td>Res</td><td>IMF-fixdate，恒 GMT</td><td><a href="/Front2Full/manual/computer-programming/http11/http-date">日期</a></td></tr><tr><td><code>ETag</code></td><td>Res</td><td><strong>双引号必需</strong>；<code>W/</code> 区分大小写</td><td><a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件</a></td></tr><tr><td><code>Expect</code></td><td>Req ⚠️</td><td>仅 <code>100-continue</code>；未知值 → <code>417</code></td><td><a href="/Front2Full/manual/computer-programming/http11/connection-management">连接</a></td></tr><tr><td><code>Expires</code></td><td>Res</td><td>绝对时刻；优先级低于 <code>max-age</code></td><td><a href="/Front2Full/manual/computer-programming/http11/caching">缓存</a></td></tr><tr><td><code>Forwarded</code></td><td>Req</td><td><code>for=</code>/<code>by=</code>/<code>host=</code>/<code>proto=</code>；IPv6 须 <code>&quot;[…]&quot;</code></td><td><a href="/Front2Full/manual/computer-programming/http11/proxy-fields">代理</a></td></tr><tr><td><code>From</code></td><td>Req</td><td>邮箱；无鉴权语义</td><td><a href="/Front2Full/manual/computer-programming/http11/context-fields">上下文</a></td></tr><tr><td><code>Host</code></td><td>Req</td><td><strong>必需且唯一</strong>；缺失 → <code>400</code></td><td><a href="/Front2Full/manual/computer-programming/http11/request-line">请求行</a></td></tr><tr><td><code>If-Match</code></td><td>Req</td><td><strong>强比较</strong>；失败 → <code>412</code></td><td><a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件</a></td></tr><tr><td><code>If-Modified-Since</code></td><td>Req</td><td>仅 GET/HEAD；被 <code>If-None-Match</code> 压制</td><td><a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件</a></td></tr><tr><td><code>If-None-Match</code></td><td>Req</td><td><strong>弱比较</strong>；命中 → <code>304</code></td><td><a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件</a></td></tr><tr><td><code>If-Range</code></td><td>Req</td><td><strong>强验证器</strong>；不匹配 → 完整 <code>200</code></td><td><a href="/Front2Full/manual/computer-programming/http11/range-requests">范围</a></td></tr><tr><td><code>If-Unmodified-Since</code></td><td>Req</td><td>仅在无 <code>If-Match</code> 时求值</td><td><a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件</a></td></tr><tr><td><code>Keep-Alive</code></td><td>Req/Res ⚠️</td><td><code>timeout=</code>/<code>max=</code>；仅为提示</td><td><a href="/Front2Full/manual/computer-programming/http11/connection-management">连接</a></td></tr><tr><td><code>Last-Modified</code></td><td>Res</td><td>弱验证器；不得晚于 <code>Date</code></td><td><a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件</a></td></tr><tr><td><code>Link</code></td><td>Res</td><td><code>&lt;uri&gt;; rel=…</code>，尖括号必需</td><td><a href="/Front2Full/manual/computer-programming/http11/context-fields">上下文</a></td></tr><tr><td><code>Location</code></td><td>Res</td><td>可为相对引用；<code>201</code> 中语义不同</td><td><a href="/Front2Full/manual/computer-programming/http11/status-3xx">3xx</a></td></tr></tbody></table><h2 id="m–z" tabindex="-1">M–Z <a class="header-anchor" href="#m–z" aria-label="Permalink to &quot;M–Z&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>方向</th><th>语法要点</th><th>详解</th></tr></thead><tbody><tr><td><code>Max-Forwards</code></td><td>Req</td><td>仅 TRACE/OPTIONS；转发前减 1</td><td><a href="/Front2Full/manual/computer-programming/http11/proxy-fields">代理</a></td></tr><tr><td><code>Proxy-Authenticate</code></td><td>Res ⚠️</td><td>配 <code>407</code></td><td><a href="/Front2Full/manual/computer-programming/http11/authentication">认证</a></td></tr><tr><td><code>Proxy-Authorization</code></td><td>Req ⚠️</td><td>逐跳，不可转发</td><td><a href="/Front2Full/manual/computer-programming/http11/authentication">认证</a></td></tr><tr><td><code>Range</code></td><td>Req</td><td><strong>闭区间</strong>；仅 GET 有定义</td><td><a href="/Front2Full/manual/computer-programming/http11/range-requests">范围</a></td></tr><tr><td><code>Referer</code></td><td>Req</td><td>拼写少一个 r；禁含 fragment</td><td><a href="/Front2Full/manual/computer-programming/http11/context-fields">上下文</a></td></tr><tr><td><code>Retry-After</code></td><td>Res</td><td>秒数或日期；数字开头即秒</td><td><a href="/Front2Full/manual/computer-programming/http11/context-fields">上下文</a></td></tr><tr><td><code>Server</code></td><td>Res</td><td>同 UA 语法；宜精简</td><td><a href="/Front2Full/manual/computer-programming/http11/context-fields">上下文</a></td></tr><tr><td><code>Set-Cookie</code></td><td>Res</td><td><strong>绝不可合并</strong>；每个一行</td><td><a href="/Front2Full/manual/computer-programming/http11/cookies">Cookie</a></td></tr><tr><td><code>TE</code></td><td>Req ⚠️</td><td>须列入 <code>Connection</code></td><td><a href="/Front2Full/manual/computer-programming/http11/message-body-length">成帧</a></td></tr><tr><td><code>Trailer</code></td><td>Req/Res</td><td>声明 trailer 区将出现的字段</td><td><a href="/Front2Full/manual/computer-programming/http11/field-syntax">字段语法</a></td></tr><tr><td><code>Transfer-Encoding</code></td><td>Req/Res ⚠️</td><td><code>chunked</code> 必须在末位</td><td><a href="/Front2Full/manual/computer-programming/http11/message-body-length">成帧</a></td></tr><tr><td><code>Upgrade</code></td><td>Req/Res ⚠️</td><td>须配 <code>Connection: Upgrade</code></td><td><a href="/Front2Full/manual/computer-programming/http11/connection-management">连接</a></td></tr><tr><td><code>User-Agent</code></td><td>Req</td><td>可嵌套 comment；不可信</td><td><a href="/Front2Full/manual/computer-programming/http11/context-fields">上下文</a></td></tr><tr><td><code>Vary</code></td><td>Res</td><td>缺失 = 缓存投毒；<code>*</code> = 不可复用</td><td><a href="/Front2Full/manual/computer-programming/http11/content-negotiation">协商</a></td></tr><tr><td><code>Via</code></td><td>Req/Res</td><td>追加到<strong>末尾</strong>，顺序即路径</td><td><a href="/Front2Full/manual/computer-programming/http11/proxy-fields">代理</a></td></tr><tr><td><code>WWW-Authenticate</code></td><td>Res</td><td><code>401</code> 中<strong>必需</strong></td><td><a href="/Front2Full/manual/computer-programming/http11/authentication">认证</a></td></tr></tbody></table><h2 id="十个最易错的细节" tabindex="-1">十个最易错的细节 <a class="header-anchor" href="#十个最易错的细节" aria-label="Permalink to &quot;十个最易错的细节&quot;">​</a></h2><ol><li><code>Content-Length</code> 是<strong>十进制</strong>，chunk-size 是<strong>十六进制</strong>。</li><li><code>Range: bytes=0-499</code> 是 <strong>500</strong> 字节（两端闭区间）。</li><li><code>Content-Range</code> 用 <strong>SP</strong> 分隔单位（<code>bytes 0-499/10000</code>），<code>Range</code> 用 <strong><code>=</code></strong>。</li><li><code>ETag</code> 的<strong>双引号是语法的一部分</strong>，不能省。</li><li><code>Set-Cookie</code> <strong>不可</strong>合并成一行——<code>Expires</code> 里有逗号。</li><li>Cookie 的 <code>Domain</code> <strong>不写反而更严格</strong>（不含子域）。</li><li><code>Accept</code> 的匹配<strong>特异性优先于 q 值</strong>。</li><li><code>If-None-Match</code> 存在时，<code>If-Modified-Since</code> 被<strong>完全忽略</strong>。</li><li><code>no-cache</code> 是「用前先验证」，<code>no-store</code> 才是「不存」。</li><li>漏发 <code>Vary</code> 会导致 CDN 把压缩版发给不支持的客户端。</li></ol><h2 id="收尾" tabindex="-1">收尾 <a class="header-anchor" href="#收尾" aria-label="Permalink to &quot;收尾&quot;">​</a></h2><p>全专栏基准为 <strong>RFC 9110 / 9111 / 9112</strong>（2022-06）。与 HTTP/2、HTTP/3 的分界：</p><ul><li><strong>仍然适用</strong>：全部字段语义、方法、状态码、条件请求、范围请求、缓存、认证（归 RFC 9110，跨版本通用）。</li><li><strong>已被取代</strong>：报文成帧、<code>Transfer-Encoding</code>/<code>chunked</code>、<code>Connection</code> 与逐跳字段、<code>Upgrade</code>、<code>Keep-Alive</code>、<code>reason-phrase</code>（归 RFC 9112，HTTP/1.1 专属；HTTP/2+ 由二进制帧层负责）。</li></ul><p>换句话说，<a href="/Front2Full/manual/computer-programming/http11/message-format">第 1 部分</a>是 HTTP/1.1 独有的，第 2、3 部分的知识在 HTTP/2 与 HTTP/3 上原样成立。</p>',14)])])}const h=d(a,[["render",n]]);export{u as __pageData,h as default};
